import pandas as pd, numpy as np
d=pd.read_csv('spectrum.csv')
x=d.shift_cm1.values; y=d.intensity.values
for lo in range(60,1100,40):
    m=(x>=lo)&(x<lo+40)
    if m.sum(): print(f'{lo:5d}-{lo+40:5d} mean {y[m].mean():8.1f} min {y[m].min():8.1f} max {y[m].max():8.1f}')
# fine look at high-y regions
for lo,hi in [(250,280),(355,385),(510,530),(60,120),(900,1100)]:
    m=(x>=lo)&(x<=hi)
    print('---',lo,hi)
    for xi,yi in zip(x[m][::2],y[m][::2]): print(f'{xi:8.2f} {yi:9.1f}')
" | head -300

